(43, 'login.Page Title', '{\"ar\":\"\\u062a\\u0633\\u062c\\u064a\\u0644 \\u0627\\u0644\\u062f\\u062e\\u0648\\u0644 | \\u0644\\u0648\\u062d\\u0629 \\u0625\\u062f\\u0627\\u0631\\u0629 \\u0645\\u0643\\u062a\\u0628\\u0629 \\u0627\\u0644\\u0643\\u062a\\u0628\",\"en\":\"Login | Library Management Dashboard\"}', '2026-02-10 08:31:52', '2026-02-10 08:31:52'),
