(45, 'login.Sidebar Welcome Desc', '{\"ar\":\"\\u0642\\u0645 \\u0628\\u062a\\u0633\\u062c\\u064a\\u0644 \\u0627\\u0644\\u062f\\u062e\\u0648\\u0644 \\u0644\\u0644\\u0648\\u0635\\u0648\\u0644 \\u0625\\u0644\\u0649 \\u0644\\u0648\\u062d\\u0629 \\u0627\\u0644\\u062a\\u062d\\u0643\\u0645 \\u0627\\u0644\\u0634\\u0627\\u0645\\u0644\\u0629 \\u0644\\u0645\\u0643\\u062a\\u0628\\u062a\\u0643. \\u064a\\u0645\\u0643\\u0646\\u0643 \\u0625\\u062f\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0643\\u062a\\u0628\\u060c \\u0627\\u0644\\u0645\\u0633\\u062a\\u062e\\u062f\\u0645\\u064a\\u0646\\u060c \\u0627\\u0644\\u0625\\u0639\\u0627\\u0631\\u0627\\u062a\\u060c \\u0648\\u0627\\u0644\\u062a\\u0642\\u0627\\u0631\\u064a\\u0631 \\u0628\\u0643\\u0644 \\u0633\\u0647\\u0648\\u0644\\u0629.\",\"en\":\"Login to access your comprehensive library dashboard. You can manage books, users, loans, and reports with ease.\"}', '2026-02-10 08:31:52', '2026-02-10 08:31:52'),
