(795, 'dashboard.Please ensure your CSV file has the following columns in order:', '{\"ar\":\"\\u064a\\u0631\\u062c\\u0649 \\u0627\\u0644\\u062a\\u0623\\u0643\\u062f \\u0645\\u0646 \\u0623\\u0646 \\u0645\\u0644\\u0641 CSV \\u064a\\u062d\\u062a\\u0648\\u064a \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0623\\u0639\\u0645\\u062f\\u0629 \\u0627\\u0644\\u062a\\u0627\\u0644\\u064a\\u0629 \\u0628\\u0627\\u0644\\u062a\\u0631\\u062a\\u064a\\u0628:\",\"en\":\"Please ensure your CSV file has the following columns in order:\"}', '2026-02-10 08:40:30', '2026-02-10 08:40:30'),
(796, 'dashboard.Heading row is required in the CSV file.', '{\"ar\":\"\\u064a\\u062c\\u0628 \\u0648\\u062c\\u0648\\u062f \\u0633\\u0637\\u0631 \\u0627\\u0644\\u0639\\u0646\\u0627\\u0648\\u064a\\u0646 (Heading) \\u0641\\u064a \\u0645\\u0644\\u0641 CSV.\",\"en\":\"Heading row is required in the CSV file.\"}', '2026-02-10 08:40:30', '2026-02-10 08:40:30'),
(797, 'dashboard.Images Instruction', '{\"ar\":\"\\u0627\\u0631\\u0641\\u0639 \\u0627\\u0644\\u0635\\u0648\\u0631 \\u062f\\u0627\\u062e\\u0644 \\u0645\\u062c\\u0644\\u062f public\\/imports\\u060c \\u0627\\u062c\\u0639\\u0644 \\u0644\\u0643\\u0644 \\u0645\\u0646\\u062a\\u062c \\u0645\\u062c\\u0644\\u062f\\u0627\\u064b \\u062e\\u0627\\u0635\\u0627\\u064b (\\u0645\\u062b\\u0644 1\\u060c 2\\u060c 3) \\u0648\\u0636\\u0639\\u0647 \\u0641\\u064a \\u0639\\u0645\\u0648\\u062f image_folder. \\u0633\\u064a\\u062a\\u0645 \\u0623\\u062e\\u0630 \\u0623\\u0648\\u0644 \\u0635\\u0648\\u0631\\u0629 (\\u062d\\u0633\\u0628 \\u0627\\u0644\\u062a\\u0631\\u062a\\u064a\\u0628 \\u0627\\u0644\\u0623\\u0628\\u062c\\u062f\\u064a) \\u0643\\u0635\\u0648\\u0631\\u0629 \\u0623\\u0633\\u0627\\u0633\\u064a\\u0629 \\u0648\\u0627\\u0644\\u0628\\u0627\\u0642\\u064a \\u0643\\u0645\\u0639\\u0631\\u0636 \\u0635\\u0648\\u0631.\",\"en\":\"Upload images to public\\/imports directory. Create a subfolder for each product (e.g., 1, 2, 3) and specify its name in the image_folder column. The first image (alphabetical order) will be the main image, and others will be gallery images.\"}', '2026-02-10 08:40:30', '2026-02-10 08:40:30'),
